// Os caminhos de erro já possuem resposta própria.
if (
  $('Prepare Error').isExecuted ||
  $('Prepare Storage Error').isExecuted
) {
  return [];
}

const items = $('Edit Fields')
  .all()
  .map(item => item.json);

const parameters = $('Define Search Parameters').first().json;
const file = $('Convert to File').first().binary?.data;

if (!file?.fileName) {
  throw new Error('Nome do arquivo processado indisponível.');
}

return [{
  json: {
    success: true,
    status: 'success',
    source: parameters.source,
    tag: parameters.tag.replace(' ', ''),
    execution_id: $execution.id,
    count: items.length,
    items,
    storage: {
      bucket: 'communitylab-assets',
      object_path: `processed/${file.fileName}`,
      status: 'success',
    },
  },
}];
